export const code = async (inputs) => {
  const candidates = [];

  // Gmail results
const emails = inputs.emailResults?.messages || [];
  for (const email of emails) {
    candidates.push({
      source: "email",
      sourceId: email.id,
      raw: email
    });
  }

  // Drive results
  const files = inputs.driveResults?.files || [];
  for (const file of files) {
    candidates.push({
      source: "drive",
      sourceId: file.id,
      raw: file
    });
  }

  return {
    candidates,
    count: candidates.length
  };
};

