export const code = async (inputs) => {
  const data = inputs.extractedData;
  const state = inputs.processedState || { fingerprints: [], last_email_check: null, last_drive_check: null };

  // Build fingerprint: sorted attendee emails + call date
  const emails = (data.attendees || [])
    .map(a => {
      const match = a.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
      return match ? match[0].toLowerCase() : a.toLowerCase();
    })
    .sort()
    .join(",");
  const fingerprint = `${emails}|${data.callDate || ""}`;

  const alreadyProcessed = (state.fingerprints || []).includes(fingerprint);

  return {
    fingerprint,
    alreadyProcessed,
    isGarbled: data.isGarbled || false,
    isInternalOnly: data.isInternalOnly || false,
    shouldSkip: alreadyProcessed || data.isGarbled || data.isInternalOnly,
    skipReason: alreadyProcessed ? "duplicate" : data.isGarbled ? "garbled" : data.isInternalOnly ? "internal" : null
  };
};

export const code = async (inputs) => {
  return {
    summary: `Skipped: transcript for ${inputs.company || "this call"} was garbled/unreadable and could not be processed.`
  };
};

export const code = async (inputs) => {
  const reasonText = inputs.reason === "duplicate"
    ? "call already processed (duplicate)"
    : inputs.reason === "internal"
    ? "internal-only call, no external contact"
    : "flagged for skip";
  return {
    summary: `Skipped: ${inputs.company || "this call"} — ${reasonText}.`
  };
};

export const code = async (inputs) => {
  const attendees = inputs.attendees || [];
  // Find first attendee that isn't "You" (assume that's your own team)
  const clientAttendee = attendees.find(a => !a.toLowerCase().startsWith("you"));
  const match = clientAttendee ? clientAttendee.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) : null;
  return { contactEmail: match ? match[0] : "" };
};

export const code = async (inputs) => {
  const state = inputs.currentState || { fingerprints: [], last_email_check: null, last_drive_check: null };
  const fingerprints = state.fingerprints || [];
  if (!fingerprints.includes(inputs.newFingerprint)) {
    fingerprints.push(inputs.newFingerprint);
  }
  return {
    fingerprints,
    last_email_check: new Date().toISOString(),
    last_drive_check: state.last_drive_check
  };
};

